namespace FiveStar.Formats.Pso;

/// <summary>The member type codes of L-format PSO schemas (low byte of a member's type word).</summary>
public enum PsoTypeCode : byte
{
    Bool = 0x01,
    Struct = 0x05,
    StructPointer = 0x07,
    Pointer08 = 0x08,
    Unknown0C = 0x0C,
    Unknown0D = 0x0D,
    S8 = 0x10,
    U8 = 0x11,
    S16 = 0x12,
    U16 = 0x13,
    S32 = 0x14,
    U32 = 0x15,
    U64 = 0x16,
    S64 = 0x17,
    F16 = 0x20,
    F32 = 0x21,
    F64 = 0x23,
    Vec2 = 0x30,
    Vec3 = 0x31,
    Vec3Packed = 0x32,
    Vec4 = 0x33,
    Vec3V = 0x34,
    Mat34 = 0x35,
    Mat44 = 0x36,
    String40 = 0x40,
    String42 = 0x42,
    String44 = 0x44,
    Hash = 0x4A,
    Hash4B = 0x4B,
    NamespacedHash = 0x4D,
    NamespacedHash64 = 0x4F,
    FixedArray = 0x50,
    AtArray = 0x52,
    FixedArray53 = 0x53,
    FixedArray54 = 0x54,
    Array = 0x5C,
    Enum8 = 0x60,
    Enum16 = 0x61,
    Enum32 = 0x62,
    Bits8 = 0x63,
    Bits16 = 0x64,
    Bits32 = 0x65,
    Bits64 = 0x68,
    Map71 = 0x71,
    Map73 = 0x73,
    Map75 = 0x75,
    Map76 = 0x76,
    Map77 = 0x77,
}
